// RealSense D435i housing. Origin: base centre on the floor. Front glass faces -Y.
$fn = 64;
L = 90;  H = 25;  D = 25.05;   // datasheet envelope
r_e = 1.0;                     // edge break (not dimensioned, conservative)
inset = 2.0; gt = 1.0;         // front glass recess (not dimensioned)
m3_pitch = 45; m3_d = 3.0; m3_depth = 3;   // rear mounting, datasheet
tri_d = 6.35; tri_depth = 5.5;             // 1/4-20 UNC, depth not dimensioned
usb_w = 8.94; usb_h = 3.26; usb_depth = 7.0; // USB-C pocket; floor seats the receptacle back (x = 38)
lens_seat = 3.2;               // lens bore floor 3.2 mm behind the front face = lens module back (0.2 recess + 3 long)
lenses = [[-32.5, 10], [-11.5, 7], [17.5, 10], [32.5, 8]]; // [x, aperture d] right IR, projector, left IR, RGB

module stad(l, h) hull() for (s = [-1, 1]) translate([s*(l/2 - h/2), 0]) circle(d = h, $fn = 96);

// Rounded stadium, clipped to the exact datasheet envelope (removes facet error).
module body()
  intersection() {
    translate([0, 0, H/2]) minkowski() {
      rotate([90, 0, 0]) linear_extrude(D - 2*r_e, center = true) stad(L - 2*r_e, H - 2*r_e);
      sphere(r = r_e / cos(180/24) / cos(180/24), $fn = 24);
    }
    translate([0, 0, H/2]) rotate([90, 0, 0]) linear_extrude(D, center = true) stad(L, H);
  }

difference() {
  body();
  // front cover-glass recess
  translate([0, -D/2 + gt, H/2]) rotate([90, 0, 0]) linear_extrude(gt + 0.5) stad(L - 2*inset, H - 2*inset);
  // lens bores behind the glass; floor seats each lens module
  for (l = lenses) translate([l[0], -D/2 - 0.1, H/2]) rotate([-90, 0, 0]) cylinder(d = l[1] + 0.2, h = lens_seat + 0.1);
  // rear M3 threaded holes (modelled at nominal 3.0)
  for (s = [-1, 1]) translate([s*m3_pitch/2, D/2 + 0.01, H/2]) rotate([90, 0, 0]) cylinder(d = m3_d, h = m3_depth + 0.01);
  // bottom 1/4-20 tripod hole at body centre
  translate([0, 0, -0.01]) cylinder(d = tri_d, h = tri_depth);
  // USB-C pocket on the +X end, long axis along Y
  translate([L/2, 0, H/2]) cube([2*usb_depth, usb_w + 0.3, usb_h + 0.3], center = true);
}

// Front cover glass. Origin: centre of its front face (flush with the housing front). Extends +Y.
$fn = 96;
L = 90; H = 25; inset = 2.0; gt = 1.0; clr = 0.15;
lenses = [[-32.5, 10], [-11.5, 7], [17.5, 10], [32.5, 8]];
module stad(l, h) hull() for (s = [-1, 1]) translate([s*(l/2 - h/2), 0]) circle(d = h);
difference() {
  rotate([-90, 0, 0]) linear_extrude(gt) stad(L - 2*inset - 2*clr, H - 2*inset - 2*clr);
  // apertures in the mask for the lens modules
  for (l = lenses) translate([l[0], -0.1, 0]) rotate([-90, 0, 0]) cylinder(d = l[1] + 0.1, h = gt + 0.2);
}

// USB-C receptacle shell. Origin: centre of the housing end face; the shell extends -X into the body.
$fn = 32;
w = 8.94; h = 3.26; wall = 0.25; len = 6.5; recess = 0.5;
tongue = [len - 1.5, 6.6, 0.7];
module stad(a, b) hull() for (s = [-1, 1]) translate([0, s*(a/2 - b/2)]) circle(d = b);
translate([-recess, 0, 0]) rotate([0, -90, 0]) {
  difference() {
    linear_extrude(len) stad(w, h);
    translate([0, 0, -0.1]) linear_extrude(len - 0.8) stad(w - 2*wall, h - 2*wall);
  }
}
// contact tongue
translate([-recess - len + tongue[0]/2 + 0.8, 0, 0]) cube(tongue, center = true);

// Lens module. Origin: centre of the front face (0.2 mm behind the glass front). Extends +Y.
$fn = 48; d = 10; len = 3;
difference() {
  rotate([-90, 0, 0]) cylinder(d = d, h = len);
  translate([0, -0.01, 0]) rotate([-90, 0, 0]) cylinder(d = d*0.45, h = 0.6);  // shallow pupil recess
}

// Lens module. Origin: centre of the front face. Extends +Y.
$fn = 48; d = 10; len = 3;
difference() {
  rotate([-90, 0, 0]) cylinder(d = d, h = len);
  translate([0, -0.01, 0]) rotate([-90, 0, 0]) cylinder(d = d*0.45, h = 0.6);
}

// Projector module. Origin: centre of the front face. Extends +Y.
$fn = 48; d = 7; len = 3;
difference() {
  rotate([-90, 0, 0]) cylinder(d = d, h = len);
  translate([0, -0.01, 0]) rotate([-90, 0, 0]) cylinder(d = d*0.5, h = 0.6);
}

// RGB lens module. Origin: centre of the front face. Extends +Y.
$fn = 48; d = 8; len = 3;
difference() {
  rotate([-90, 0, 0]) cylinder(d = d, h = len);
  translate([0, -0.01, 0]) rotate([-90, 0, 0]) cylinder(d = d*0.45, h = 0.6);
}
